function save(){try{localStorage.setItem(STORAGE,JSON.stringify({v:6,workstation:workstation?.state(),view:{zoom:targetZoom,center:targetCenter.toArray(),free:zoomed},forms:extension?.state(),imprints:savedImprints([...nails.map(n=>n.actions),...history.flatMap(h=>h.kind==='reset'?h.before.nails:h.kind==='sculpt'?[h.before.actions]:[])],stamper?.state().imprintId),stamp:stamper?.state(),charms:charms?.state()||[],colorIndex,material:materialType,object:objectType,tool,magnet:nails.map(n=>n.magnetTarget.toArray()),nails:nails.map(n=>n.actions),history}));}catch{toast('This browser could not save your set. Keep this tab open.');}}
function restore(){try{const data=migrate(JSON.parse(localStorage.getItem(STORAGE)||'null'));if(!data)return;workstation.restore(data.workstation);customPigment=normalizeHex(data.workstation?.custom);extension.restore(data.forms);restoreImprints(data.imprints,validAction);stamper.restore(data.stamp);for(let i=0;i<10;i++){nails[i].actions=(Array.isArray(data.nails[i])?data.nails[i]:[]).filter(validAction);rebuild(nails[i]);if(Array.isArray(data.magnet?.[i])&&data.magnet[i].length===2&&data.magnet[i].every(v=>Number.isFinite(v)&&Math.abs(v)<=1)){nails[i].magnetTarget.fromArray(data.magnet[i]);nails[i].mesh.material.uniforms.magnet.value.copy(nails[i].magnetTarget);}}charms.restore(data.charms);history=Array.isArray(data.history)?data.history.filter(a=>a&&((a.kind==='reset'&&Array.isArray(a.before?.forms)&&a.before.forms.length===10&&a.before.forms.every(validForm)&&Array.isArray(a.before.nails)&&a.before.nails.length===10&&a.before.nails.every(arr=>Array.isArray(arr)&&arr.every(validAction))&&Array.isArray(a.before.charms)&&a.before.charms.every(validCharm))||(a.kind==='sculpt'&&Number.isInteger(a.id)&&a.id>=0&&a.id<10&&validForm(a.before?.form)&&Array.isArray(a.before?.actions)&&a.before.actions.every(validAction)&&Array.isArray(a.before.charms)&&a.before.charms.every(validCharm))||(a.kind==='charm'&&Array.isArray(a.before)&&a.before.length<=400&&a.before.every(validCharm))||(!a.kind&&Number.isInteger(a.id)&&a.id>=0&&a.id<10))):[];colorIndex=Number.isInteger(data.colorIndex)&&data.colorIndex>=0&&data.colorIndex<palette.length?data.colorIndex:0;tool=toolNames.includes(data.tool)?data.tool:'brush';materialType=materials.includes(data.material)?data.material:'cream';objectType=objects.includes(data.object)?data.object:'star';if(data.view&&Number.isFinite(data.view.zoom)&&Array.isArray(data.view.center)&&data.view.center.length===2&&data.view.center.every(v=>Number.isFinite(v)&&Math.abs(v)<5000)){targetZoom=clampZoom(data.view.zoom);targetCenter.fromArray(data.view.center);zoomed=data.view.free===true||Math.abs(targetZoom-1)>.01||Math.abs(targetCenter.x)>.01;root.classList.toggle('zoomed',zoomed);}if(history.length)root.classList.add('painting');}catch{}}
const materialNotes={cream:'opaque pigment · build a coat',jelly:'one gesture, one translucent glaze',pearl:'a little silk in the light',chrome:'move nearby to catch the light',glitter:'each pass deposits more flakes',magnetic:'hover near a nail to draw the band',matte:'soft pigment · no reflection',gloss:'one curved stroke of light'};
function updateBottleFinish(){document.querySelectorAll('.bottle').forEach((b,i)=>{b.dataset.material=b.classList.contains('selected')?materialType:'cream';});}
function pickMaterial(m){commitStroke();charms?.cancel();materialType=m;document.querySelectorAll('#materials [data-material]').forEach(b=>{b.setAttribute('aria-pressed',b.dataset.material===m);b.classList.toggle('changed',b.dataset.material===m);});$('#material-note').textContent=materialNotes[m];updateBottleFinish();tone('tool');scheduleSave();}
materials.forEach(m=>{const b=document.createElement('button');b.textContent=m;b.dataset.material=m;b.setAttribute('aria-label',m+' material');b.setAttribute('aria-pressed',false);b.onclick=()=>pickMaterial(m);$('#materials').append(b);});
function pickObject(o){objectType=o;document.querySelectorAll('[data-object]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.object===o));scheduleSave();}
objects.forEach((o,i)=>{const b=document.createElement('button');b.textContent=['★','✦','●','♡','PEARL'][i];b.dataset.object=o;b.setAttribute('aria-label',o+' decoration');b.onclick=()=>pickObject(o);$('#object-tray').append(b);});
