charms=createCharmSystem({scene,camera,renderer,nails,specs,root,hit,localPoint,toast,tone,selectNail,commitStroke,pickTool,closeup,tool:()=>tool,record:a=>history.push(a),save:scheduleSave,status:updateStatus});
stamper=createStampSystem({root,renderer,nails,specs,camera,hit,localPoint,pickTool,commitStroke,selectNail,tone,save:scheduleSave,zoomOut,zoomed:()=>zoomed,tool:()=>tool,presenting:()=>presenting,transfer:(n,a)=>{applyTransfer(n,a);n.actions.push(a);n.finishType=a.material;history.push({id:n.id});refreshTextures(n);scheduleSave();updateStatus();}});
extension=createExtensionSystem({root,nails,specs,group,camera,renderer,hit,localPoint,selectNail,commitStroke,record:a=>history.push(a),save:scheduleSave,status:updateStatus,tone,charms:()=>charms,trim:(n,form)=>{const a={tool:'trim',surface:JSON.parse(JSON.stringify(form)),points:[]};trimSurface(n,form);n.actions.push(a);refreshTextures(n);},frame:frameNail,closeup,zoomed:()=>zoomed,presenting:()=>presenting,overview,exit:()=>pickTool('brush')});
curing=createCuring({root,group,nails,charms:()=>charms,present,tone,sound:()=>soundOn,save,exportImage:async share=>{renderer.render(scene,camera);const canvas=document.createElement('canvas');canvas.width=renderer.domElement.width;canvas.height=renderer.domElement.height;const ctx=canvas.getContext('2d');ctx.drawImage(renderer.domElement,0,0);ctx.fillStyle='#65594a';ctx.font=Math.round(canvas.width*.024)+'px Georgia';ctx.fillText('nail study',canvas.width*.05,canvas.height*.09);ctx.font=Math.round(canvas.width*.009)+'px sans-serif';ctx.fillText('NO. 01 / FINISHED',canvas.width*.05,canvas.height*.12);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)return;const file=new File([blob],'nail-study.png',{type:'image/png'});if(share&&navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'Nail Study'});return;}catch(e){if(e.name==='AbortError')return;}}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='nail-study.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(share?'Your image is ready to share.':'Your manicure is kept as an image.');},reset:()=>{const before={forms:extension.state(),nails:nails.map(n=>n.actions),charms:charms.state()};history.push({kind:'reset',before});for(const n of nails){n.actions=[];rebuild(n);}extension.restore();charms.restore([]);zoomOut();updateStatus();}});
restore();overview();pickColor(customPigment||colorIndex);pickTool(tool);pickMaterial(materialType);pickObject(objectType);updateStatus();window.addEventListener('pagehide',()=>{extension.finish();stamper.finish();commitStroke();charms.cancel();save();});
function coverage(n){const p=n.ctx.getImageData(0,0,SIZE,Math.round(SIZE*span(n.form))).data;let sum=0;for(let i=3;i<p.length;i+=4)sum+=p[i];return Math.round(sum/(SIZE*Math.round(SIZE*span(n.form))*255)*10000)/10000;}
function paintPath(input){if(!input||!Number.isInteger(input.nail)||input.nail<0||input.nail>9||!paintTools.includes(input.tool)||!materials.includes(input.material)||!Number.isInteger(input.color)||input.color<0||input.color>9||!Array.isArray(input.points)||!input.points.length||input.points.length>500||!input.points.every(p=>Array.isArray(p)&&p.length===2&&p.every(v=>Number.isFinite(v)&&v>=0&&v<=1))||(input.pigment!==undefined&&!normalizeHex(input.pigment))||(input.tool==='pick'&&!objects.includes(input.object)))throw Error('Provide a valid nail, pigment, material, tool and normalized points.');commitStroke();const n=nails[input.nail],a={surface:JSON.parse(JSON.stringify(n.form)),tool:input.tool,color:input.color,pigment:normalizeHex(input.pigment)||palette[input.color].color,opacity:workstation.settings[input.tool]?.opacity??1,density:workstation.settings[input.tool]?.density??1,material:input.material,object:input.object||'star',seed:Math.floor(Math.random()*2147483647)+1,points:[]};const radii={brush:58,liner:7,dot:21,fan:96,pick:44,erase:30};const layer=startLayer(n,a);let prev;for(const v of input.points){const p={x:v[0]*SIZE,y:v[1]*SIZE*span(n.form),r:radii[a.tool]*(workstation.settings[a.tool]?.size||1)};if(prev&&['dot','pick'].includes(a.tool))break;const steps=prev?Math.max(1,Math.ceil(Math.hypot(p.x-prev.x,p.y-prev.y)/(p.r*.24))):1;for(let k=1;k<=steps;k++){const q=prev?{x:prev.x+(p.x-prev.x)*k/steps,y:prev.y+(p.y-prev.y)*k/steps,r:p.r}:p;a.points.push(q);addStamp(layer,q);}prev=p;}applyLayer(n,layer);refreshTextures(n);stroke={id:n.id,action:a,layer};selectNail(n.id);commitStroke();return {nail:n.id,coverage:coverage(n),flakes:n.particles.length,decorations:n.objects.length};}
