const context=document.modelContext,lifecycle=new AbortController();if(context?.registerTool){for(const def of [{name:'set_nail_view',description:'Zoom the continuous canvas around a normalized screen focal point. Changes view only.',inputSchema:{type:'object',properties:{zoom:{type:'number',minimum:.65,maximum:4},x:{type:'number',minimum:0,maximum:1},y:{type:'number',minimum:0,maximum:1}},required:['zoom','x','y'],additionalProperties:false},execute:input=>{if(presenting||![input.zoom,input.x,input.y].every(Number.isFinite)||input.x<0||input.x>1||input.y<0||input.y>1)throw Error('Invalid view');commitStroke();const r=renderer.domElement.getBoundingClientRect();view.zoomAt(input.zoom,r.left+input.x*r.width,r.top+input.y*r.height);return {zoom:targetZoom,center:targetCenter.toArray()};}},{name:'paint_nail_path',description:'Paint one coat or place one decoration on a nail using normalized points; modifies the locally saved design.',inputSchema:{type:'object',properties:{nail:{type:'integer',minimum:0,maximum:9},tool:{type:'string',enum:paintTools},material:{type:'string',enum:materials},color:{type:'integer',minimum:0,maximum:9},pigment:{type:'string',pattern:'^#[0-9a-fA-F]{6}$'},object:{type:'string',enum:objects},points:{type:'array',items:{type:'array',items:{type:'number',minimum:0,maximum:1},minItems:2,maxItems:2},minItems:1,maxItems:500}},required:['nail','tool','material','color','points'],additionalProperties:false},annotations:{readOnlyHint:false},execute:paintPath},{name:'select_nail_material',description:'Select material for future strokes without changing existing paint.',inputSchema:{type:'object',properties:{material:{type:'string',enum:materials}},required:['material'],additionalProperties:false},execute:input=>{if(!materials.includes(input?.material))throw Error('Unknown material');pickMaterial(input.material);return {material:materialType};}},{name:'move_nail_magnet',description:'Move the virtual magnet over a nail. The luminous band interpolates toward this position.',inputSchema:{type:'object',properties:{nail:{type:'integer',minimum:0,maximum:9},x:{type:'number',minimum:-1,maximum:1},y:{type:'number',minimum:-1,maximum:1}},required:['nail','x','y'],additionalProperties:false},execute:async input=>{if(!Number.isInteger(input?.nail)||input.nail<0||input.nail>9||![input.x,input.y].every(v=>Number.isFinite(v)&&Math.abs(v)<=1))throw Error('Invalid magnet position');nails[input.nail].magnetTarget.set(input.x,input.y);scheduleSave();return {target:{x:input.x,y:input.y}};}},{name:'read_nail_set',description:'Read the locally saved nail set and selected tool.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({view:{zoom:targetZoom,center:targetCenter.toArray()},curing:curing.state(),workstation:workstation.state(),stamp:stamper.inspect(),charms:charms.state(),selectedCharm:charms.selected(),tool,material:materialType,object:objectType,color:customPigment||palette[colorIndex].name,nails:nails.map(n=>({name:n.name,form:n.form,strokes:n.actions.length,transfers:n.actions.filter(a=>a.tool==='stamp').map(a=>({mirror:a.mirror,offset:a.offset,includeBase:a.includeBase,imprintId:a.imprintId})),hasBase:hasBase(n.actions),finish:n.finishType,flakes:n.particles.length,decorations:n.objects.length,coverage:coverage(n),magnet:{x:n.mesh.material.uniforms.magnet.value.x,y:n.mesh.material.uniforms.magnet.value.y}}))})},{name:'select_nail_art_tool',description:'Pick a physical brush and polish bottle. Does not paint a nail.',inputSchema:{type:'object',properties:{tool:{type:'string',enum:toolNames},color:{type:'integer',minimum:0,maximum:9}},required:['tool','color'],additionalProperties:false},execute:input=>{if(!input||!toolNames.includes(input.tool)||!Number.isInteger(input.color)||input.color<0||input.color>9)throw Error('Choose a valid tool and polish index 0–9.');pickTool(input.tool);pickColor(input.color);return {tool,color:palette[colorIndex].name};}},{name:'undo_nail_stroke',description:'Undo the most recent painting action across the ten nails.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>({undone:undo()})}]){try{Promise.resolve(context.registerTool(def,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort());}
